import { DEMO_CONTENT } from '../config/features';

/**
 * Offline content packs (owner-approved source: Sefaria; nusach Sefard for v1 – 2026-11-23).
 * Generated by scripts/content/fetch-sefaria.mjs. Loaded on demand so they don't weigh on startup.
 * Status: PENDING_RABBINIC_REVIEW – shown with that notice in the reader.
 */
export type Segment = { text: string; note?: boolean };

export type SiddurSection = {
  ref: string;
  heTitle: string;
  versionTitle: string;
  license: string;
  versionSource: string;
  sha256: string;
  segments: Segment[];
};

export type SiddurGroup = 'weekday' | 'shabbat' | 'holiday';

export type SiddurPrayer = { id: string; group: SiddurGroup; title: string; sections: SiddurSection[] };

export type SiddurPack = {
  id: string;
  version: string;
  title: string;
  nusach: 'sefard' | 'ashkenaz';
  fetchedAt: string;
  source: { name: string; ref: string; url: string };
  approval: 'PENDING_RABBINIC_REVIEW' | 'APPROVED';
  prayers: SiddurPrayer[];
};

export type TehillimPack = {
  id: string;
  version: string;
  title: string;
  fetchedAt: string;
  source: { name: string; ref: string; versionTitle: string; license: string; versionSource: string; url: string };
  sha256: string;
  approval: 'PENDING_RABBINIC_REVIEW' | 'APPROVED';
  chapters: Array<{ chapter: number; verses: string[] }>;
};

export type SiddurIndex = Omit<SiddurPack, 'prayers' | 'id'> & { id: string; prayers: Array<Pick<SiddurPrayer, 'id' | 'group' | 'title'>> };

export const SIDDUR_GROUP_TITLES: Record<SiddurGroup, string> = {
  weekday: 'ימות החול',
  shabbat: 'שבת',
  holiday: 'ראש חודש, מועדים וחגים',
};

/** Small list of every prayer (titles and groups only). */
export const loadSiddurIndex = async (nusach: 'sefard' | 'ashkenaz' = 'sefard'): Promise<SiddurIndex> =>
  // The Ashkenaz pack is not approved for distribution: only an internal build contains it (the
  // constant removes this import from a production bundle).
  DEMO_CONTENT && nusach === 'ashkenaz'
    ? ((await import('./packs/siddur-ashkenaz-index.json')).default as unknown as SiddurIndex)
    : ((await import('./packs/siddur-sefard-index.json')).default as SiddurIndex);

/** The texts of one group, loaded only when a prayer of that group is opened. */
export async function loadSiddurGroup(group: SiddurGroup, nusach: 'sefard' | 'ashkenaz' = 'sefard'): Promise<SiddurPack> {
  if (DEMO_CONTENT && nusach === 'ashkenaz') {
    const a =
      group === 'weekday'
        ? await import('./packs/siddur-ashkenaz-weekday.json')
        : group === 'shabbat'
          ? await import('./packs/siddur-ashkenaz-shabbat.json')
          : await import('./packs/siddur-ashkenaz-holiday.json');
    return a.default as unknown as SiddurPack;
  }
  const mod =
    group === 'weekday'
      ? await import('./packs/siddur-sefard-weekday.json')
      : group === 'shabbat'
        ? await import('./packs/siddur-sefard-shabbat.json')
        : await import('./packs/siddur-sefard-holiday.json');
  return mod.default as SiddurPack;
}

export const loadTehillim = async (): Promise<TehillimPack> => (await import('./packs/tehillim.json')).default as TehillimPack;

/** Licenses that allow bundling in the app (CC-BY requires the attribution shown in the reader). */
export const ALLOWED_LICENSES = ['Public Domain', 'CC0', 'CC-BY'];

export function attributionFor(section: Pick<SiddurSection, 'versionTitle' | 'license'>): string {
  return `${section.versionTitle} · ${section.license} · דרך ספריא`;
}

/* --------------------------- Tehillim by month --------------------------- */

/** A slice of Tehillim: whole chapters, or a verse range of one chapter (Psalm 119). */
export type TehillimRange = { from: number; to: number; verses?: [number, number] };

/**
 * Traditional division of the book by day of the Hebrew month.
 * Days 25–26 split Psalm 119; in a 29-day month day 29 also reads day 30's portion.
 */
export const MONTHLY_TEHILLIM: TehillimRange[][] = [
  [{ from: 1, to: 9 }], [{ from: 10, to: 17 }], [{ from: 18, to: 22 }], [{ from: 23, to: 28 }], [{ from: 29, to: 34 }],
  [{ from: 35, to: 38 }], [{ from: 39, to: 43 }], [{ from: 44, to: 48 }], [{ from: 49, to: 54 }], [{ from: 55, to: 59 }],
  [{ from: 60, to: 65 }], [{ from: 66, to: 68 }], [{ from: 69, to: 71 }], [{ from: 72, to: 76 }], [{ from: 77, to: 78 }],
  [{ from: 79, to: 82 }], [{ from: 83, to: 87 }], [{ from: 88, to: 89 }], [{ from: 90, to: 96 }], [{ from: 97, to: 103 }],
  [{ from: 104, to: 105 }], [{ from: 106, to: 107 }], [{ from: 108, to: 112 }], [{ from: 113, to: 118 }],
  [{ from: 119, to: 119, verses: [1, 96] }], [{ from: 119, to: 119, verses: [97, 176] }],
  [{ from: 120, to: 134 }], [{ from: 135, to: 139 }], [{ from: 140, to: 144 }], [{ from: 145, to: 150 }],
];

/** Portion for a day of the Hebrew month (1–30); monthLength 29 adds day 30 to day 29. */
export function tehillimForDay(day: number, monthLength: 29 | 30): TehillimRange[] {
  const d = Math.min(Math.max(1, day), 30);
  if (monthLength === 29 && d === 29) return [...MONTHLY_TEHILLIM[28]!, ...MONTHLY_TEHILLIM[29]!];
  return MONTHLY_TEHILLIM[d - 1]!;
}

export function rangeLabel(ranges: TehillimRange[], numeral: (n: number) => string): string {
  return ranges
    .map((r) =>
      r.verses
        ? `${numeral(r.from)} (פסוקים ${numeral(r.verses[0])}–${numeral(r.verses[1])})`
        : r.from === r.to
          ? numeral(r.from)
          : `${numeral(r.from)}–${numeral(r.to)}`,
    )
    .join(', ');
}
